  'ai_history_invalid_dates': { 'zh-CN': '开始日期不能晚于结束日期。', 'en': 'The start date must not follow the end date.' },
  'ai_history_reset': { 'zh-CN': '清空筛选并查询', 'en': 'Clear Filters & Load' },
  'ai_history_filter_scope': { 'zh-CN': '新结果按任务创建日期（北京时间），旧建议按建议日期筛选；人物须由您选择。新结果的人物筛选仅匹配直接关联人物的任务，不包含所有活动参与记录。', 'en': 'Results use task creation dates in Beijing time; legacy advice uses recommendation dates. Choose the person yourself. Person filters match direct task subjects, not every activity participation.' },
  'ai_history_runtime_scope': { 'zh-CN': '按已完成的 AI 任务分页，同一任务可能有多条结果；生成完成不代表业务已执行。', 'en': 'Pages contain completed AI tasks, which may have multiple results. Generation completion does not mean business execution.' },
  'ai_history_legacy_scope': { 'zh-CN': '按旧建议原记录分页；名称为历史快照。旧执行标记不等同于新系统的实际结果。', 'en': 'Pages contain original legacy advice; names are historical snapshots. Legacy execution flags are not new-system outcomes.' },
  'ai_history_page_info': { 'zh-CN': '第 {page} 页 · 本页 {count} 条任务／建议 · 未统计总数', 'en': 'Page {page} · {count} tasks / advice records on this page · Total not counted' },
  'ai_history_related_limit': { 'zh-CN': '本页部分结果、反馈或关联记录达到读取上限，当前展示不代表完整历史。请缩小筛选范围，并核对原业务记录。', 'en': 'Some results, feedback or linked records reached a read limit. This is not the complete history. Narrow the filters and check original business records.' },
  'ai_history_recent_only': { 'zh-CN': '当前响应为旧接口的近期记录，不能据此判断完整历史或总数。', 'en': 'This response contains recent records from the previous API, not a complete history or total.' },
  'ai_history_read_only': { 'zh-CN': '只读来源', 'en': 'Read-only Source' },
  'ai_history_legacy_status': { 'zh-CN': '旧建议执行标记', 'en': 'Legacy Advice Status' },
  'ai_history_status_unrecorded': { 'zh-CN': '未记录', 'en': 'Not Recorded' },
  'ai_history_readonly_note': { 'zh-CN': '旧建议在此只读，原编号不用于新结果反馈、实际结果关联或学习审核。今后请在 Console 人物页生成新建议并人工确认。', 'en': 'Legacy advice is read-only here. Its IDs are not used for new feedback, outcomes, or learning reviews. Generate and confirm new advice in Console People.' },
  'ai_history_snapshot_name': { 'zh-CN': '历史姓名快照', 'en': 'Historical Name Snapshot' },
