  'ai_history_metrics_scope': { 'zh-CN': '以上为近30天全局反馈指标，不随下方历史筛选变化。', 'en': 'These are global feedback metrics for the last 30 days, independent of history filters.' },
  'ai_history_execution_unknown': { 'zh-CN': '业务执行状态：本页未核实，请查对应业务记录。人工采纳不等于已执行；下方实际结果与经验审核分别记录。', 'en': 'Business execution is not verified here; check the related business record. Acceptance does not mean execution. Actual outcomes and learning reviews are recorded separately below.' },
  'ai_history_load_preserved': { 'zh-CN': '查询失败，当前已显示的历史和范围保持不变，请重试。', 'en': 'The query failed. Displayed history and its scope are preserved; retry.' },
