  'legacy_opp_note': { 'zh-CN': '修改原机会记录，不另建副本。先核对服务端差异预览，再确认保存；客户和人物归属不能在此修改。', 'en': 'Update the original opportunity. Review the server-generated changes before confirming. Customer and person associations cannot be changed here.' },
  'legacy_opp_unavailable': { 'zh-CN': '此机会暂不符合新编辑入口条件，请核对人物关联或使用旧客户入口。', 'en': 'This opportunity is not eligible for this editor. Check its person association or use the legacy customer page.' },
  'legacy_opp_preview': { 'zh-CN': '生成服务端预览', 'en': 'Generate Server Preview' },
