  'legacy_opp_preview_failed': { 'zh-CN': '预览未生成，输入已保留。请核对类型、阶段、日期及当前关联后重试。', 'en': 'Preview failed; your inputs are preserved. Check the type, stage, dates and current associations, then retry.' },
  'legacy_opp_stale': { 'zh-CN': '记录、关联或预览已变化／过期，未执行本次修改。输入已保留，请重新生成预览。', 'en': 'The record, association or preview changed or expired. This update was not executed. Inputs are preserved; generate a new preview.' },
  'legacy_opp_execute_failed': { 'zh-CN': '尚未收到执行成功回执。输入和预览已保留，可重试同一凭证；系统会避免重复保存。', 'en': 'No success receipt received. Inputs and preview are preserved; retry the same receipt to avoid duplicate writes.' },
