  'legacy_opp_read_again': { 'zh-CN': '重新读取原记录', 'en': 'Read Original Again' },
  'legacy_opp_directory_refresh_failed': { 'zh-CN': '原记录已核对，机会列表刷新失败，请重新打开列表。', 'en': 'Original record verified. The opportunity list could not refresh; reopen the list.' },
  'file_import_title': { 'zh-CN': '导入资料', 'en': 'Import Documents' },
  'file_import_entry': { 'zh-CN': '导入文件并核对资料', 'en': 'Import & Review Documents' },
  'file_import_choose': { 'zh-CN': '选择待导入文件', 'en': 'Choose files to import' },
  'file_import_note': { 'zh-CN': '每个文件最多4MB，本次最多10个。先保存原件，再按需解析；支持JPEG/PNG/WebP、UTF-8文本（TXT/CSV）和每页均可提取文字的未加密PDF。PDF最多20页，提取限8秒；文本最多10万字。候选资料须经人工核对后应用。', 'en': 'Up to 4 MB per file and 10 files per queue. Save originals first; optionally parse JPEG/PNG/WebP, UTF-8 TXT/CSV or unencrypted PDFs with text on every page. PDF: up to 20 pages and 8 seconds for extraction. Text: up to 100,000 characters. Review before applying.' },
  'l04_pdf_encrypted': { 'zh-CN': '原件已保存。PDF已加密，暂不支持解析；请自行取得可使用的未加密副本后重新导入。', 'en': 'Original saved. Encrypted PDFs cannot be parsed. Obtain an authorized unencrypted copy and import it again.' },
  'l04_pdf_no_text': { 'zh-CN': '原件已保存。PDF至少有一页没有可提取文字（可能是扫描页或空白页），未生成不完整草稿。请转换为文字PDF、拆分文件，或将扫描页作为图片导入。', 'en': 'Original saved. At least one PDF page has no extractable text (possibly scanned or blank). No partial draft was created. Convert to a text PDF, split the file, or import scanned pages as images.' },
  'l04_pdf_limit': { 'zh-CN': '原件已保存。PDF超出20页、10万字或解析资源限制，未截断生成草稿。请拆分文件后重新导入。', 'en': 'Original saved. The PDF exceeds 20 pages, 100,000 characters or parsing resource limits. No truncated draft was created. Split the file and import again.' },
  'l04_pdf_timeout': { 'zh-CN': '原件已保存。PDF文字提取超过8秒，已停止。可重试；若再次超时，请拆分文件。', 'en': 'Original saved. PDF text extraction exceeded 8 seconds and stopped. Retry, or split the file if it times out again.' },
  'file_import_save': { 'zh-CN': '保存原件', 'en': 'Save Original' },
  'file_import_save_parse': { 'zh-CN': '保存并解析', 'en': 'Save & Parse' },
  'file_import_save_all': { 'zh-CN': '保存全部原件', 'en': 'Save All Originals' },
  'file_import_parse_all': { 'zh-CN': '保存并解析支持的文件', 'en': 'Save All & Parse Supported Files' },
  'file_import_clear': { 'zh-CN': '清空本次列表', 'en': 'Clear Queue' },
  'file_import_clear_pending': { 'zh-CN': '有文件尚未确认保存成功。清空后将失去本次重试编号；请先刷新历史确认是否已保存。仍要清空吗？', 'en': 'Some saves are unconfirmed. Clearing loses their retry keys; refresh history to check for saved files first. Clear anyway?' },
  'file_import_history': { 'zh-CN': '导入历史与重试', 'en': 'Import History & Retry' },
