  'file_import_no_history': { 'zh-CN': '当前账号暂无导入记录。旧附件和OCR记录仍在原列表中。', 'en': 'No imports for this account. Existing attachments and OCR records remain in their original lists.' },
  'file_import_review': { 'zh-CN': '审核已保存草稿', 'en': 'Review Saved Draft' },
